import { type CliErrorCode, type RetryHint } from "@uipath/common";
import { type FeedScope } from "./feed-resolver";
/** Discriminator for {@link DeployFailure}; library callers can ignore the tag and read `.message`/`.instructions`. */
export type DeployFailureReason = "auth_failed" | "folder_resolution_failed" | "config_file_not_found" | "config_file_read_failed" | "config_file_parse_failed" | "install_request_failed"
/** Personal Workspace deploy via AS auto-install failed (publish first, then retry). */
 | "personal_workspace_deploy_failed"
/** A --feed value couldn't be resolved to a selectable feed. */
 | "feed_resolution_failed"
/** Folder-feed deploy via AS auto-install failed (publish to the feed first, then retry). */
 | "feed_deploy_failed"
/** The requested deploy location isn't the feed folder or one of its descendants. */
 | "location_outside_feed"
/**
 * Redeploy blocked: a deployment for this solution already exists (HTTP 400
 * "Deployment exists in a failed or running state") and must be upgraded in
 * place instead of redeployed.
 */
 | "deployment_exists"
/** Recovery: deployment completed but flagged "Needs Setup" — manual config required before activation. */
 | "needs_setup_to_activate"
/** Recovery: deployment completed, ready to activate — auto-activation didn't run. */
 | "ready_to_activate"
/** Recovery: deployment completed but activation failed (terminal). */
 | "activation_failed_post_deploy"
/** Recovery or final-status: the deploy itself failed (e.g. ValidationFailed). */
 | "deploy_failed"
/** Poll completed with `outcome === Completed` but `data` is undefined (defensive). */
 | "no_final_status"
/** Poll loop didn't complete cleanly AND the search service had no recovery to surface. */
 | "poll_timeout" | "poll_failed" | "poll_aborted"
/** Activation HTTP request failed (post-deploy path). */
 | "activation_request_failed"
/** Activation poll didn't reach a terminal state. */
 | "activation_poll_failed"
/** Activation reached a terminal state but it was a failure. */
 | "activation_failed";
export interface DeployOptions {
    /** Override the active tenant for auth + folder-lookup. The CLI's deprecated `--tenant` flag flows through here. */
    tenant?: string;
    /** Pin auth (+ folder lookup) to this exact `.uipath/.auth` path. */
    envFilePath?: string;
    /** Name for the deployment (`uip solution deploy run -n`). */
    deploymentName: string;
    /** Package name to deploy. */
    packageName: string;
    /** Package version (semver) to deploy. */
    packageVersion: string;
    /** Name of the new Orchestrator folder created for this deployment. */
    folderName: string;
    /** Mutually exclusive with `parentFolderKey` and `personalWorkspace`. */
    parentFolderPath?: string;
    /** Mutually exclusive with `parentFolderPath` and `personalWorkspace`. */
    parentFolderKey?: string;
    /** Deploy into the user's Personal Workspace; resolves the workspace name automatically. */
    personalWorkspace?: boolean;
    /** Deploy a package from a specific feed (name or folder key). Mutually exclusive with `personalWorkspace`. */
    feed?: string;
    /** Path to a JSON / YAML configuration file. */
    configFile?: string;
    /** Per-poll-phase timeout in seconds (deploy and, when not skipped, activate). Default 360. */
    timeout?: number;
    /** Milliseconds between polls. Default 5000. */
    pollInterval?: number;
    /** Minimum minutes before token expiration to trigger a refresh. Default 10. */
    loginValidity?: number;
    /**
     * Feed / Personal Workspace deploys only: poll the new deployment to a
     * terminal state instead of returning as soon as the install is accepted.
     * The tenant path always polls, so this changes nothing there.
     */
    wait?: boolean;
    /** Skip auto-activation; leave deployment in "Inactive (Ready to activate)" state. */
    skipActivate?: boolean;
    /**
     * Deploy even when the package already has a deployment in the target feed.
     * Off by default: `deploy run` always creates a *new* deployment in a *new*
     * folder, so repeating it quietly multiplies folders (UV-15362). Callers
     * that really do want a second, independent copy opt in here.
     */
    yes?: boolean;
    /** Host-side cancellation for both poll loops (e.g. VS Code's cancel button); replaces `processContext.pollSignal`. */
    signal?: AbortSignal;
}
export interface DeploySuccess {
    ok: true;
    /**
     * Tenant path: `"DeploymentSucceeded"` after polling reaches terminal.
     * Feed/PW path: `"DeploymentStarted"` — the AS auto-install endpoint
     * returns at request acceptance, before terminal state is observable — or
     * `"DeploymentSucceeded"` when `wait` was set and the poll got there.
     */
    status: string;
    /** Tenant only — populated from Pipelines install result. Feed/PW returns no key. */
    deploymentKey?: string | null;
    /** Tenant only — Pipelines deployment id. Undefined for feed/PW (no Pipelines call). */
    pipelineDeploymentId?: string;
    /** Allows `null` so `"InstanceId": null` reaches JSON output when the SDK reports null. */
    instanceId?: string | null;
    folderName: string;
    folderPath: string;
    /**
     * Set only when the deployment did NOT land in the folder the caller asked
     * for. Orchestrator collision-renames a taken solution-root name rather
     * than reusing the folder, so `--folder-name MySolution` can silently
     * become `MySolution 1` (UV-15346). Carries the requested name so the
     * caller can see both.
     */
    requestedFolderName?: string;
    /** "SuccessfulActivate" | "Skipped" | "NoInstance" — short canonical token. Feed/PW path emits `"Auto"` (server-side activation) or `"Skipped"`. */
    activationStatus: string;
    /** Feed/PW only — the caller-chosen deployment name (`--name`). */
    deploymentName?: string;
    /** Feed/PW only — package name as deployed. */
    packageName?: string;
    /** Feed/PW only — package version as deployed. */
    packageVersion?: string;
    /** Feed/PW only — future-tense human guidance ("Check status with..."). */
    nextSteps?: string;
    /** Which feed the deploy targeted — drives telemetry `target`. Defaults to tenant. */
    feedKind?: FeedScope["kind"];
}
export interface DeployFailure {
    ok: false;
    reason: DeployFailureReason;
    /** OutputFormatter.error Message: short summary. */
    message: string;
    /** OutputFormatter.error Instructions: remediation guidance. */
    instructions: string;
    /** Recommended exit code (1 default; 2 reserved for `poll_timeout` — CI distinguishability). */
    exitCode: number;
    /** Set whenever an install was initiated (post-`pipelinesInstall` paths). */
    pipelineDeploymentId?: string;
    /**
     * Set whenever the failure mode is known, so the CLI does not fall back to
     * `OutputFormatter`'s guess. The guess is wrong for a poll that timed out:
     * the message carries no HTTP status, so it defaults to `unknown_error` /
     * `RetryWillNotFix` while the instructions right next to it say the deploy
     * may still be running.
     */
    errorCode?: CliErrorCode;
    retry?: RetryHint;
}
export type DeployResult = DeploySuccess | DeployFailure;
/**
 * Programmatic core of `uip solution deploy run`: auth → folder → optional
 * config file → install → poll (with 404 → search-service fallback) →
 * optional auto-activate. Returns a tagged {@link DeployResult}; re-throws
 * only on unexpected SDK errors. Threads `options.signal` through both polls.
 * Does not touch `OutputFormatter`/`processContext`.
 */
export declare function deployRunAsync(options: DeployOptions): Promise<DeployResult>;
